    static Class<?> javaForSelf(String t) {
        if (t == null || t.equals("FlatString") || t.equals("JavaString")) return null;
        if (t.equals("Int")) return int.class;
        if (t.equals("Long") || t.equals("UnsignedLong")) return long.class;
